def compute_mean_pos(block):
    """Return mean (row,col) position of 7s within block, normalized to [0,1]"""
    offset = block == 7
    if offset.sum() == 0:
        return np.zeros(2)
    # Get positions where block == 7
    finds = np.argwhere(offset)
    # Add row offset and column offset
    positions = finds + np.array([[block.shape[0]/2, block.shape[1]/2]])
    return positions.mean(axis=0)

